"use client";

/**
 * FilterTray. Chunky filter pads in one long well, with the action at its
 * end. A pad that's on is a lit cap, lit from inside; the action carries the
 * count. Apply, and the lit pads fold into the action cap (Morph) and it
 * becomes one key that says how many are on, with their names engraved on the
 * tray's floor beside it; press that key and they come back out.
 *
 * Every pad is a HardwareButton: its icon on the cap, its name engraved under
 * it and said as its accessible name, `aria-pressed` for its state.
 */
import { forwardRef, useEffect, useRef, useState, type ReactNode } from "react";
import type { EchoInterop } from "echo-ui-core/types";
import { HardwareButton } from "../hardware-button";
import { Morph } from "../morph";
import { SizeProvider, type ControlSize } from "../size";
import { Scope } from "../scope";
import "./filter-tray.css";

export interface FilterTrayOption {
  value: string;
  /** Engraved under the pad, and the pad's accessible name. */
  label: string;
  /** The glyph on the pad. */
  icon: ReactNode;
  /** A colour of its own for this pad, as a hex: it lights in it when it's on (a Scope). */
  accent?: string;
}

export interface FilterTrayProps extends EchoInterop {
  /** What the pads filter: the tray's accessible name. */
  label: string;
  options: readonly FilterTrayOption[];
  /** The pads that are on (controlled). */
  value?: readonly string[];
  defaultValue?: readonly string[];
  onValueChange?: (value: string[]) => void;
  /** Folded into the action (controlled). */
  applied?: boolean;
  defaultApplied?: boolean;
  /** Called when the pads fold in (true) or come back out (false). */
  onAppliedChange?: (applied: boolean) => void;
  /** The action's word. Default "Filter". */
  actionLabel?: string;
  /** Height on the control scale for every pad. Default `lg`. */
  size?: ControlSize;
}

const plural = (n: number) => `${n} filter${n === 1 ? "" : "s"}`;

/**
 * `forwardRef`, not a `ref` prop — see the note on `Field`. The ref lands on
 * the tray.
 */
export const FilterTray = forwardRef<HTMLDivElement, FilterTrayProps>(function FilterTray(
  {
    label,
    options,
    value,
    defaultValue,
    onValueChange,
    applied,
    defaultApplied = false,
    onAppliedChange,
    actionLabel = "Filter",
    size = "lg",
    disabled = false,
    name,
    ...interop
  },
  ref,
) {
  const [innerValue, setInnerValue] = useState<readonly string[]>(defaultValue ?? []);
  const on = value ?? innerValue;
  const [innerApplied, setInnerApplied] = useState(defaultApplied);
  const appliedNow = applied ?? innerApplied;
  const folded = appliedNow && on.length > 0;

  const setOn = (next: string[]) => {
    if (value === undefined) setInnerValue(next);
    onValueChange?.(next);
  };
  const setFolded = (next: boolean) => {
    if (applied === undefined) setInnerApplied(next);
    onAppliedChange?.(next);
  };

  // Nothing on is nothing applied: once the pads are cleared (from outside,
  // or never chosen), the next pad lights without folding the tray, and a
  // controlled `applied` hears that it's off.
  const setFoldedRef = useRef(setFolded);
  setFoldedRef.current = setFolded;
  useEffect(() => {
    if (appliedNow && on.length === 0) setFoldedRef.current(false);
  }, [appliedNow, on.length]);

  const chosen = options.filter((o) => on.includes(o.value));
  const names = chosen.map((o) => o.label).join(", ");
  const count = chosen.length;

  return (
    <div
      ref={ref}
      className="echo-filter-tray"
      role="group"
      aria-label={label}
      data-size={size}
      data-folded={folded || undefined}
      {...interop}
    >
      {folded ? (
        <span className="echo-filter-tray__summary" aria-hidden="true">
          {chosen.map((o) => o.label).join(" · ")}
        </span>
      ) : null}
      <SizeProvider size={size}>
        <Morph
          align="end"
          status={folded ? `${plural(count)} on: ${names}` : ""}
          onEscape={folded ? () => setFolded(false) : undefined}
        >
          {folded ? (
            <HardwareButton
              data-morph="action"
              variant="primary"
              disabled={disabled}
              aria-label={`${plural(count)}: ${names}. Change filters`}
              onClick={() => setFolded(false)}
            >
              {plural(count)}
            </HardwareButton>
          ) : (
            <>
              {options.map((o) => {
                const pressed = on.includes(o.value);
                const pad = (
                  <HardwareButton
                    key={o.value}
                    iconOnly
                    icon={o.icon}
                    aria-label={o.label}
                    caption={o.label}
                    aria-pressed={pressed}
                    variant={pressed ? "primary" : "neutral"}
                    disabled={disabled}
                    onClick={() => setOn(pressed ? on.filter((v) => v !== o.value) : [...on, o.value])}
                  />
                );
                return o.accent ? (
                  <Scope key={o.value} accent={o.accent}>
                    {pad}
                  </Scope>
                ) : (
                  pad
                );
              })}
              <HardwareButton
                data-morph="action"
                variant="primary"
                disabled={disabled || count === 0}
                aria-label={count ? `${actionLabel}: ${plural(count)}` : `${actionLabel}: choose a filter first`}
                onClick={() => setFolded(true)}
              >
                {count ? `${actionLabel} · ${count}` : actionLabel}
              </HardwareButton>
            </>
          )}
        </Morph>
      </SizeProvider>
      {name ? on.map((v) => <input key={v} type="hidden" name={name} value={v} />) : null}
    </div>
  );
});

/**
 * FilterTray. One long well, as ButtonGroup's: the pads give up their own
 * wells and sit on its floor, names engraved under them, the action at the
 * far end. Composes var(--echo-*) — no hex literals; the only fixed values
 * are the single-key-light occlusion model.
 */
.echo-filter-tray {
  --ft-well: var(--echo-space-3, 6px);
  /* A pad's cap: the control height less the well it would have had. */
  --ft-cap: calc(var(--echo-control-large, 60px) - 2 * var(--echo-space-2, 4px));
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: var(--echo-space-6);
  box-sizing: border-box;
  inline-size: 100%;
  min-inline-size: 0;
  padding: var(--ft-well) var(--ft-well) var(--echo-space-2);
  /* A pad, its gap and two lines of name, so wrapping names never move it. */
  min-block-size: calc(
    var(--ft-well) + var(--ft-cap) + var(--echo-space-4, 8px) + 2 * var(--echo-leading-tight, 1.25) * var(--echo-text-3xs, 0.625rem) +
      var(--echo-space-2, 4px)
  );
  /* The well's corner follows a pad's, a well's width out. */
  --ft-radius: calc(var(--echo-radius-xl) + var(--ft-well));
  border-radius: var(--ft-radius);
  box-shadow:
    inset 0 3px 7px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.7 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.06 * var(--echo-gloss, 1)));
}

/* The pads and the action sit on the tray's floor, not in wells of their own. */
.echo-filter-tray .echo-hw__well {
  padding: 0;
  box-shadow: none;
}
.echo-filter-tray[data-size="md"] {
  --ft-cap: calc(var(--echo-control-default, 44px) - 2 * var(--echo-space-2, 4px));
}
.echo-filter-tray[data-size="sm"] {
  --ft-cap: calc(var(--echo-control-compact, 32px) - 2 * var(--echo-space-1, 2px));
}
/* Icons read at a pad's size. */
.echo-filter-tray[data-size="lg"] .echo-hw {
  --hw-icon: var(--echo-icon-xl, 28px);
}
.echo-filter-tray[data-size="md"] .echo-hw {
  --hw-icon: var(--echo-icon-lg, 20px);
}

/* A pad's name wraps under it rather than pushing its neighbours away. */
.echo-filter-tray .echo-hw__caption {
  inline-size: calc(var(--hw-h) + var(--echo-space-6));
  letter-spacing: var(--echo-tracking-wider, 0.12em);
  line-height: var(--echo-leading-tight, 1.25);
}

.echo-filter-tray > .echo-morph {
  flex: 1 1 auto;
  min-inline-size: 0;
  justify-items: stretch;
}
.echo-filter-tray .echo-morph__row {
  justify-content: flex-start;
  align-items: flex-start;
}
/* The action is always the last key: it keeps to the tray's far end. */
.echo-filter-tray .echo-morph__row > .echo-hw:last-child {
  margin-inline-start: auto;
}

/*
 * Folded: what's on, engraved on the floor beside the one key. Laid over the
 * floor rather than taking room in it, so the tray keeps its size and the key
 * lands where it rests while the pads fold into it.
 */
.echo-filter-tray__summary {
  position: absolute;
  inset-block-start: calc(var(--ft-well) + var(--ft-cap) / 2);
  inset-inline-start: calc(var(--ft-well) + var(--echo-space-5));
  inset-inline-end: calc(50% - var(--echo-space-8));
  translate: 0 -50%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-wider, 0.12em);
  text-transform: uppercase;
  color: var(--echo-text-dim);
  pointer-events: none;
}

/* Once the pads have folded into the key, the tray settles to one row. */
.echo-filter-tray[data-folded] {
  min-block-size: calc(2 * var(--ft-well) + var(--ft-cap));
  transition: min-block-size var(--echo-duration-sweep) var(--echo-ease-glide) var(--echo-duration-pop);
}
@media (prefers-reduced-motion: reduce) {
  .echo-filter-tray[data-folded] {
    transition: none;
  }
}

@media (forced-colors: active) {
  .echo-filter-tray {
    border: var(--echo-border-hairline, 1px) solid CanvasText;
  }
}
